  ('form_01', 'ቅጽ 01፡ በ{year} በጀት ዓመት 2ኛ ሩብ ዓመት እስከ ታህሳስ 25 ድረስ በየደረጃው የተዋቀረ የኮሚሽን መዋቅር የሚያሳይ ሠንጠረዥ', '[{"key":"ወረዳ","subKeys":["ብዛት","ያዋቀሩ","ያላዋቀሩ"]},{"key":"በብልፅግና ህብረት ደረጃ","subKeys":["ብዛት","ያዋቀሩ","ያላዋቀሩ"]},{"key":"ጠቅላላ ድምር","subKeys":["ብዛት","ያዋቀሩ","ያላዋቀሩ"]},{"key":"ያዋቀሩ %","subKeys":[]}]'::jsonb, NOW()),
  ('form_02', 'ቅጽ 02፡ በ{year} በጀት ዓመት 2ኛ ሩብ ዓመት እስከ ታህሳስ 25 ድረስ በየደረጃው የሚገኙ የኮሚሽን አባላት የሚያሳይ ሠንጠረዥ', '[{"key":"የወረዳ ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"የብልፅግና ህብረት ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"ጠቅላላ ድምር","subKeys":["ወ","ሴ","ድ"]}]'::jsonb, NOW()),
  ('form_03', 'ቅጽ 03፡ በ{year} በጀት ዓመት 2ኛ ሩብ ዓመት እስከ ታህሳስ 25 ድረስ የኮሚሽኑ ቅርንጫፍ ጽ/ቤት ቋሚ የሰው ሀይል የሚያሳይ ሠንጠረዥ', '[{"key":"የወረዳ ኮሚሽን ጽ/ቤት","subKeys":["ጽ/ኃ","ም/ክ","ባለሙ","ጸሐ","ሹፌ","ድም"]},{"key":"ጠቅላላ ድምር","subKeys":["ጽ/ኃ","ም/ክ","ባለሙ","ጸሐ","ሹፌ","ድም"]}]'::jsonb, NOW()),
  ('form_04', 'ቅጽ 04፡ በ{year} በጀት ዓመት 2ኛ ሩብ ዓመት እስከ ታህሳስ 25 ድረስ የኮሚሽን ቅርንጫፍ ጽ/ቤት የስራ ክፍል የሚያሣይ ሠንጠረዥ', '[{"key":"የወረዳ ቅ/ጽ/ቤት","subKeys":["እቅድ","ክንውን","%"]},{"key":"ጠቅላላ ድምር","subKeys":["እቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_04_1', 'ቅጽ 04-1፡ በ{year} በጀት ዓመት 3ኛ ሩብ ዓመት እስከ ታህሳስ 25 ድረስ በየደረጃው ለሚገኙ የኮሚሽን መዋቅሮች የተመደበ በጀት የሚያሳይ ሠንጠረዥ', '[{"key":"ለወረዳ","subKeys":["ብር","ሣ"]},{"key":"ጠቅላላ ድምር","subKeys":["ብር","ሣ"]}]'::jsonb, NOW()),
  ('form_05', 'ቅጽ 05፡ የ{year} በጀት ዓመት እቅድ ያዘጋጁ በየደረጃው የሚገኙ የኮሚሽን መዋቅሮች የሚያሳይ ሠንጠረዥ', '[{"key":"ወረዳ ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"አጠቃላይ ድምር","subKeys":["እቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_06', 'ቅጽ 06፡ የ{year} በጀት ዓመት እቅድ ላይ ኦረንቴሽን የሰጡ የኮሚሽን መዋቅሮች የሚያሳይ ሠንጠረዥ', '[{"key":"ወረዳ","subKeys":["እቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"ጠቅላላ ድምር","subKeys":["እቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_06_1', 'ቅጽ 06-1፡ በ{year} በጀት ዓመት የእቅድ ኦረንቴሽን ላይ የተሳተፉ የኮሚሽን ቤተሠብ ብዛት የሚየሳይ ሠንጠረዥ', '[{"key":"በወረዳ ደረጃ","subKeys":["ወ","ሴ","ድ"]},{"key":"በብልጽግና ህብረት ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"ጠቅላላ ድምር","subKeys":["ወ","ሴ","ድ"]},{"key":"ምርመራ","subKeys":[]}]'::jsonb, NOW()),
  ('form_07', 'ቅጽ 07፡ በ{year} በጀት ዓመት 2ኛ ሩብ ዓመት እስከ መጋቢት 25 ድረስ ለኮሚሽን ጽ/ቤት ኃላፊና ለኮሚሽን አባላት የተሰጡ የግንዛቤ ማስጨበጫ ስልጠና የሚያሳይ ሠንጠረዥ', '[{"key":"በወረዳ ደረጃ","subKeys":["ወ","ሴ","ድ"]},{"key":"በብልጽግና ህብረት ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"አጠቃላይ ድምር","subKeys":["ወ","ሴ","ድ"]}]'::jsonb, NOW()),
  ('form_08', 'ቅጽ 08፡ የ{year} በጀት ዓመት 3ኛ ሩብ ዓመት ሪፖርት በየደረጃው ለሚገኙ የኮሚሽን መዋቅሮች ያቀረቡ የሚያሳይ ሠንጠረዥ', '[{"key":"ለወረዳ የላኩ የብልጽግና ህብረት","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"ለአባላት ኮንፈረንስ ሪፖርት ያቀረቡ የኮሚሽን መዋቅር ብዛት","subKeys":["ከተማ","በክፍለ ከተማ ወረዳ 1 ጊዜ","ወረዳ 1 ጊዜ","ህብረት 1 ጊዜ","ጠቅላላ ድምር"]}]'::jsonb, NOW()),
  ('form_09', 'ቅጽ 09፡ በ{year} በጀት ዓመት የ3ኛ ሩብ ዓመት ኢንስፔክሽን ያካሄዱ የኮሚሽን መዋቅሮች ብዛት የሚያሳይ ሠንጠረዥ', '[{"key":"በወረዳ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"አጠቃላይ ድምር","subKeys":["ዕቅድ","ክንውን","%"]}]'::jsonb, NOW()),
