  ('form_11', 'ቅጽ 11፡ በ{year} በጀት ዓመት የ3ኛ ሩብ ዓመት የግኝቶች ግብረ መልስ ለፓርቲ ቅርንጫፍ ጽ/ቤት የሰጡ የሚያሳይ ሠንጠረዥ', '[{"key":"በወረዳ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"አጠቃላይ ድምር","subKeys":["ዕቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_12', 'ቅጽ 12፡ በ{year} በጀት ዓመት 3ኛ ሩብ ዓመት እስከ መጋቢት 25 በየደረጃው ለሚገኙ የፓርቲ አመራርና አባላት የተሰጡ ስልጠናዎች የሚያሳይ ሠንጠረዥ', '[{"key":"በወረዳ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"አጠቃላይ ድምር","subKeys":["ዕቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_13', 'ቅጽ 13፡ በ{year} በጀት ዓመት 3ኛ ሩብ ዓመት እስከ መጋቢት 25 ድረስ የፓርቲ አባላት፣ የብልፅግና ህብረትና ቤተሰብ መረጃ የሚያሳይ ሠንጠረዥ', '[{"key":"የፓርቲ አባላት ብዛት","subKeys":["ወንድ","ሴት","ድምር"]},{"key":"አባላት የተደራጁበት አሃድ ብዛት","subKeys":["የብልፅግና ቤተሰብ ብዛት","የብልፅግና ህብረት ብዛት"]},{"key":"ከአጠቃላይ የአባላት ብዛት ወደ ዳታ ቤዝ የገባ መረጃ ብዛት","subKeys":["ወ","ሴ","ድ","%"]}]'::jsonb, NOW()),
  ('form_14', 'ቅጽ 14፡ በ{year} በጀት ዓመት 2ኛ ሩብ ዓመት እስከ መጋቢት 25 ድረስ በፓርቲ ቅ/ጽ/ቤት በአባላትና አመራር ላይ የተወሰዱ ርምጃዎች የሚያሳይ ሠንጠረዥ', '[{"key":"በ2ኛ ሩብ ዓመት የተወሰዱ እርምጃዎች","subKeys":["ተግሣጽ","የቃል ማስጠንቀቂያ","የጽሐፍ ማስጠንቀቂያ","ከሃላፊነት ዝቅ ማድረግ","ከሃላፊነት ማንሳት","ከሃላፊነት ማገድ","ከአባልነት መሠረዝ","ጠቅላላ ድምር"]},{"key":"ከአባልነት ከተሰረዙ ውስጥ በኮንፈረንስ ቀርቦ የጸደቀ","subKeys":["ብዛት","%"]}]'::jsonb, NOW()),
  ('form_15', 'ቅጽ 15፡ በ{year} በጀት ዓመት 2ኛ ሩብ ዓመት እስከ መጋቢት 25 ድረስ በየደረጃው ለሚገኙ የፓርቲ መዋቅሮች የቀረቡ ቅሬታዎችና አፈጻጸም የሚያሳይ ሠንጠረዥ', '[{"key":"የቀረቡ ቅሬታዎችና አፈጻጸም","subKeys":["የቀረቡ","የተፈቱ","በሂደት ያሉ","ሌላ","ድምር"]},{"key":"ምርመራ","subKeys":[]}]'::jsonb, NOW()),
  ('form_15_1', 'ቅጽ 15-1፡ በ{year} በጀት ዓመት 2ኛ ሩብ ዓመት እስከ ታህሳስ 25 ድረስ በየደረጃው ለሚገኙ የኮሚሽን መዋቅሮች የቀረቡ አቤቱታዎች የሚያሳይ ሠንጠረዥ', '[{"key":"የቀረቡ አቤቱታዎችና አፈጻጸማቸው","subKeys":["የቀረቡ","ውሳኔ ያገኙ","በሂደት ያሉ","የተመለሱ","ኮሚሽን የማይመለከት"]},{"key":"በኮሚሽኑ የተሰጡ ውሳኔዎች","subKeys":["የጸነ","የተሻረ","የተሻሻለ","ድምር"]},{"key":"በኮሚሽኑ ከተሰጡ ውሳኔዎች በፓርቲ መዋቅር","subKeys":["የተፈጸመ","ያልተፈጸመ","በሂደት ያለ","ድምር"]}]'::jsonb, NOW()),
  ('form_16', 'ቅጽ 16፡ በ{year} በጀት ዓመት 2ኛ ሩብ ዓመት እስከ መጋቢት 25 ድረስ የፓርቲ ቅ/ጽ/ቤት ተመዝግበው የሚገኙ የፓርቲ ሀብቶች የሚያሳይ ሠንጠረዥ', '[{"key":"ቋሚ ንብረት","subKeys":["በክፍለ ከተማ","ወረዳ","ድምር"]},{"key":"ልዩ ተንቀሳቃሽ ንብረት","subKeys":["በክፍለ ከተማ","ወረዳ","ድምር"]},{"key":"ጠቅላላ የተመዘገበ ንብረት ብዛት","subKeys":["በክፍለ ከተማ","ወረዳ","ድምር"]}]'::jsonb, NOW()),
